def source(**values):
    """Return one normalized source record with explicit defaults."""
    defaults = {
        "priority": "P3",
        "category": "Context",
        "provider": "",
        "sensor_product": "",
        "nepal_candidate": "No exact Nepal acquisition confirmed",
        "epoch_role": "Context",
        "resolution": "",
        "height_method": "None",
        "geometry": "None exposed",
        "product_needed": "",
        "what_exists": "",
        "visited_status": "Official product/access page researched",
        "provided_to_project": "No data acquired; source/access lead only",
        "usefulness": "Low",
        "verdict": "Context or archive lead",
        "principal_blocker": "Exact Nepal coverage/product not confirmed",
        "auth": "open_none",
        "current_account_status": "Not created / not required",
        "current_entitlement": "Unknown or not applicable",
        "next_action": "No immediate action",
        "source_url": "",
        "access_url": "",
        "auth_docs_url": "",
        "confidence": "Medium",
        "verified_date": "2026-08-30",
        "notes": "",
    }
    defaults.update(values)
    auth_profile = defaults.pop("auth")
    profile = AUTH_PROFILES[auth_profile]
    return {**defaults, "auth_profile": auth_profile, **profile}


